     1→import {
     2→  type CreateRoomParameters,
     3→  JoinRule,
     4→  PowerLevel_Tags,
     5→  RoomHistoryVisibility,
     6→  type RoomPowerLevelChanges,
     7→  RoomPreset,
     8→  RoomVisibility,
     9→  type UserProfile,
    10→} from "@unomed/react-native-matrix-sdk";
    11→import { MatrixCore } from "../../matrix-client/services/MatrixCore";
    12→
    13→export class RoomService {
    14→  public static getRooms = () => {
    15→    return MatrixCore.getClient().rooms();
    16→  };
    17→
    18→  public static getRoomInfo = (roomId: string) => {
    19→    if (!MatrixCore.instance)
    20→      throw new Error("Matrix client is not initialized");
    21→    const room = MatrixCore.instance.getRoom(roomId);
    22→    return room ?? null;
    23→  };
    24→
    25→  public static getExistingDirectRoom = async (
    26→    userId: string,
    27→  ): Promise<string | null> => {
    28→    const client = MatrixCore.getClient();
    29→
    30→    try {
    31→      const rooms = client.rooms();
    32→      for (const room of rooms) {
    33→        const roomInfo = await room.roomInfo();
    34→        if (roomInfo?.isDirect) {
    35→          const members = await room.members();
    36→          const memberList = members.nextChunk(100000) ?? [];
    37→          const hasUser = memberList.some((member) => member.userId === userId);
    38→          if (hasUser) return room.id();
    39→        }
    40→      }
    41→      return null;
    42→    } catch (error) {
    43→      console.error("Failed to check for existing direct room:", error);
    44→      return null;
    45→    }
    46→  };
    47→
    48→  public static getOrCreateDirectRoom = async (
    49→    userId: string,
    50→  ): Promise<string> => {
    51→    const client = MatrixCore.getClient();
    52→
    53→    try {
    54→      const existingRoomId = await RoomService.getExistingDirectRoom(userId);
    55→      if (existingRoomId) return existingRoomId;
    56→
    57→      const roomOptions: CreateRoomParameters = {
    58→        name: undefined,
    59→        topic: undefined,
    60→        preset: RoomPreset.PrivateChat,
    61→        avatar: undefined,
    62→        isEncrypted: true,
    63→        isDirect: true,
    64→        visibility: new RoomVisibility.Private(),
    65→        invite: [userId],
    66→        powerLevelContentOverride: undefined,
    67→        joinRuleOverride: undefined,
    68→        historyVisibilityOverride: undefined,
    69→        canonicalAlias: undefined,
    70→      };
    71→
    72→      const roomId = await client.createRoom(roomOptions);
    73→      await MatrixCore.refreshRoomList();
    74→      return roomId;
    75→    } catch (error) {
    76→      throw new Error(`Failed to get or create direct room: ${error}`);
    77→    }
    78→  };
    79→
    80→  public static createRoom = async (
    81→    roomName: string,
    82→    type: "private" | "public",
    83→    image: Asset | null,
    84→    roomTopic?: string,
    85→  ): Promise<string> => {
    86→    const client = MatrixCore.getClient();
    87→
    88→    try {
    89→      const roomOptions: CreateRoomParameters = {
    90→        name: roomName,
    91→        topic: roomTopic,
    92→        preset:
    93→          type === "private" ? RoomPreset.PrivateChat : RoomPreset.PublicChat,
    94→        avatar: undefined,
    95→        isEncrypted: type === "private",
    96→        isDirect: false,
    97→        visibility:
    98→          type === "private"
    99→            ? new RoomVisibility.Private()
   100→            : new RoomVisibility.Public(),
   101→        invite: [],
   102→        powerLevelContentOverride: undefined,
   103→        joinRuleOverride: undefined,
   104→        historyVisibilityOverride: undefined,
   105→        canonicalAlias: undefined,
   106→      };
   107→
   108→      const roomId = await client.createRoom(roomOptions);
   109→
   110→      if (image?.base64) {
   111→        const room = client.getRoom(roomId);
   112→        const bytes = Buffer.from(image.base64, "base64");
   113→        const mimeType = image.type ?? "image/jpeg";
   114→
   115→        if (!room) throw new Error("Room not found");
   116→        await room.uploadAvatar(mimeType, bytes.buffer, {
   117→          height: BigInt(32),
   118→          width: BigInt(32),
   119→          mimetype: mimeType,
   120→          size: BigInt(image.fileSize ?? 0),
   121→          thumbnailInfo: {
   122→            height: BigInt(32),
   123→            width: BigInt(32),
   124→            mimetype: mimeType,
   125→            size: BigInt(image.fileSize ?? 0),
   126→          },
   127→          thumbnailSource: undefined,
   128→          blurhash: "",
   129→          isAnimated: false,
   130→        });
   131→      }
   132→
   133→      await MatrixCore.refreshRoomList();
   134→      return roomId;
   135→    } catch (error) {
   136→      throw new Error(`Failed to create room: ${error}`);
   137→    }
   138→  };
   139→
   140→  public static updateRoom = async (
   141→    roomId: string,
   142→    displayName?: string,
   143→    topic?: string,
   144→    avatar?: Asset | null,
   145→  ) => {
   146→    const room = MatrixCore.getRoom(roomId);
   147→
   148→    if (displayName) await room.setName(displayName);
   149→    if (topic !== undefined) await room.setTopic(topic);
   150→
   151→    if (avatar === null) {
   152→      await room.removeAvatar();
   153→    } else if (avatar?.base64) {
   154→      const bytes = Buffer.from(avatar.base64, "base64");
   155→      const mimeType = avatar.type ?? "image/jpeg";
   156→
   157→      await room.uploadAvatar(mimeType, bytes.buffer, {
   158→        height: BigInt(32),
   159→        width: BigInt(32),
   160→        mimetype: mimeType,
   161→        size: BigInt(avatar.fileSize ?? 0),
   162→        thumbnailInfo: {
   163→          height: BigInt(32),
   164→          width: BigInt(32),
   165→          mimetype: mimeType,
   166→          size: BigInt(avatar.fileSize ?? 0),
   167→        },
   168→        thumbnailSource: undefined,
   169→        blurhash: "",
   170→        isAnimated: false,
   171→      });
   172→    }
   173→  };
   174→
   175→  public static leaveRoom = async (roomId: string) => {
   176→    const client = MatrixCore.getClient();
   177→    const room = MatrixCore.getRoom(roomId);
   178→    await room.leave();
   179→    const updatedRoom = client.getRoom(roomId);
   180→    if (!updatedRoom) throw new Error("Room not found after leave");
   181→    await updatedRoom.forget();
   182→    await MatrixCore.refreshRoomList();
   183→  };
   184→
   185→  public static joinRoomByAddress = async (address: string) => {
   186→    const client = MatrixCore.getClient();
   187→    const roomPreview = await client.getRoomPreviewFromRoomAlias(address);
   188→    const roomId = roomPreview.info().roomId;
   189→    await client.joinRoomById(roomId);
   190→    return roomId;
   191→  };
   192→
   193→  public static acceptRoomInvite = async (roomId: string) => {
   194→    const room = MatrixCore.getRoom(roomId);
   195→    await room.join();
   196→    await MatrixCore.refreshRoomList();
   197→  };
   198→
   199→  public static declineRoomInvite = async (roomId: string) => {
   200→    const room = MatrixCore.getRoom(roomId);
   201→    await room.leave();
   202→    await room.forget();
   203→    await MatrixCore.refreshRoomList();
   204→  };
   205→
   206→  public static invitePeopleToRoom = async (
   207→    roomId: string,
   208→    invitedPeople: UserProfile[],
   209→  ) => {
   210→    const room = MatrixCore.getRoom(roomId);
   211→    await Promise.all(
   212→      invitedPeople.map(({ userId }) => room.inviteUserById(userId)),
   213→    );
   214→  };
   215→
   216→  // Power levels
   217→
   218→  public static getUserPowerLevel = async (roomId: string, userId?: string) => {
   219→    if (!MatrixCore.instance) return null;
   220→    const room = MatrixCore.instance.getRoom(roomId);
   221→    if (!room) return null;
   222→
   223→    const member = await room.member(userId ?? MatrixCore.instance.userId());
   224→
   225→    return Number(
   226→      member.powerLevel.tag === PowerLevel_Tags.Value
   227→        ? member.powerLevel.inner.value
   228→        : 0,
   229→    );
   230→  };
   231→
   232→  public static getRoomPowerLevels = async (roomId: string) => {
   233→    if (!MatrixCore.instance) return null;
   234→    const room = MatrixCore.instance.getRoom(roomId);
   235→    if (!room) return null;
   236→    return room.getPowerLevels();
   237→  };
   238→
   239→  public static updateUserPowerLevels = async (
   240→    roomId: string,
   241→    updates: Array<{ userId: string; powerLevel: bigint }>,
   242→  ) => {
   243→    const room = MatrixCore.getRoom(roomId);
   244→    await room.updatePowerLevelsForUsers(updates);
   245→  };
   246→
   247→  public static applyRoomPowerLevelChanges = async (
   248→    roomId: string,
   249→    changes: RoomPowerLevelChanges,
   250→  ) => {
   251→    const room = MatrixCore.getRoom(roomId);
   252→    await room.applyPowerLevelChanges(changes);
   253→  };
   254→
   255→  public static resetRoomPowerLevels = async (roomId: string) => {
   256→    const room = MatrixCore.getRoom(roomId);
   257→    await room.resetPowerLevels();
   258→  };
   259→
   260→  // Room security
   261→
   262→  public static updateRoomJoinRule = async (
   263→    roomId: string,
   264→    isPublic: boolean,
   265→  ) => {
   266→    const room = MatrixCore.getRoom(roomId);
   267→    await room.updateJoinRules(
   268→      isPublic ? new JoinRule.Public() : new JoinRule.Invite(),
   269→    );
   270→  };
   271→
   272→  public static updateRoomHistoryVisibility = async (
   273→    roomId: string,
   274→    visibility: "joined" | "invited",
   275→  ) => {
   276→    const room = MatrixCore.getRoom(roomId);
   277→    await room.updateHistoryVisibility(
   278→      visibility === "joined"
   279→        ? new RoomHistoryVisibility.Joined()
   280→        : new RoomHistoryVisibility.Invited(),
   281→    );
   282→  };
   283→
   284→  public static enableRoomEncryption = async (roomId: string) => {
   285→    const room = MatrixCore.getRoom(roomId);
   286→    await room.enableEncryption();
   287→  };
   288→
   289→  // Moderation
   290→
   291→  public static removeUserFromRoom = async (
   292→    roomId: string,
   293→    userId: string,
   294→    reason?: string,
   295→  ) => {
   296→    const room = MatrixCore.getRoom(roomId);
   297→    await room.kickUser(userId, reason);
   298→    await MatrixCore.refreshRoomList();
   299→  };
   300→
   301→  public static banUserFromRoom = async (
   302→    roomId: string,
   303→    userId: string,
   304→    reason?: string,
   305→  ) => {
   306→    const room = MatrixCore.getRoom(roomId);
   307→    await room.banUser(userId, reason);
   308→    await MatrixCore.refreshRoomList();
   309→  };
   310→
   311→  public static unbanUserFromRoom = async (
   312→    roomId: string,
   313→    userId: string,
   314→    reason?: string,
   315→  ) => {
   316→    const room = MatrixCore.getRoom(roomId);
   317→    await room.unbanUser(userId, reason);
   318→    await MatrixCore.refreshRoomList();
   319→  };
   320→}
