    27→export const RoomDetails: React.FC<
    28→  NativeStackScreenProps<Routes, "roomDetails">
    29→> = ({ navigation, route }) => {
    30→  const { room } = route.params;
    31→  const [roomInfo, setRoomInfo] = useState<RoomInfo | undefined>(undefined);
    32→  const isFocused = useIsFocused();
    33→  const isDirect = useMemo(() => roomInfo?.isDirect, [roomInfo]);
    34→  const hasNoCallOption = useMemo(
    35→    () => roomInfo?.hasRoomCall ?? false,
    36→    [roomInfo],
    37→  );
    38→  const { isLeavingRoom, members, refreshMembers, leaveRoom } = useLeaveRoom(
    39→    room,
    40→    {
    41→      onSuccess: () => {
    42→        navigation.reset({
    43→          index: 0,
    44→          routes: [{ name: "home" }],
    45→        });
    46→      },
    47→    },
    48→  );
    49→  const [loading, setLoading] = useState(true);
    50→  const [userPowerLevel, setUserPowerLevel] = useState<number | null>(null);
    51→  const [nameLevel, setNameLevel] = useState(50);
    52→  const [avatarLevel, setAvatarLevel] = useState(50);
    53→  const [topicLevel, setTopicLevel] = useState(50);
    54→
    55→  const canSeeRoles = useMemo(
    56→    () => !!userPowerLevel && userPowerLevel >= 50,
    57→    [userPowerLevel],
    58→  );
    59→  const canEditName = useMemo(
    60→    () => (userPowerLevel ?? 0) >= nameLevel,
    61→    [userPowerLevel, nameLevel],
    62→  );
    63→  const canEditAvatar = useMemo(
    64→    () => (userPowerLevel ?? 0) >= avatarLevel,
    65→    [userPowerLevel, avatarLevel],
    66→  );
    67→  const canEditTopic = useMemo(
    68→    () => (userPowerLevel ?? 0) >= topicLevel,
    69→    [userPowerLevel, topicLevel],
    70→  );
    71→  const canEditRoom = useMemo(
    72→    () => !isDirect && (canEditName || canEditAvatar || canEditTopic),
    73→    [isDirect, canEditName, canEditAvatar, canEditTopic],
    74→  );
    75→  const pinnedEventIds = useAtomValue(TimelineAtoms.pinnedEventIds);
    76→  const otherDirectMembersId = useMemo(() => {
    77→    return members.filter(
    78→      (member) => member.userId !== MatrixCore.instance?.userId(),
    79→    )[0]?.userId;
    80→  }, [members]);
    81→
    82→  useEffect(() => {
    83→    if (!isFocused) return;
    84→
    85→    room
    86→      .roomInfo()
    87→      .then(setRoomInfo)
    88→      .catch(console.error)
    89→      .finally(() => {
    90→        setLoading(false);
    91→      });
    92→
    93→    RoomService.getUserPowerLevel(room.id())
    94→      .then(setUserPowerLevel)
    95→      .catch(console.error);
    96→
    97→    RoomService.getRoomPowerLevels(room.id())
    98→      .then((pl) => {
    99→        if (!pl) return;
   100→        const vals = pl.values();
   101→        setNameLevel(Number(vals.roomName));
   102→        setAvatarLevel(Number(vals.roomAvatar));
   103→        setTopicLevel(Number(vals.roomTopic));
   104→      })
   105→      .catch(console.error);
   106→
   107→    refreshMembers();
   108→  }, [room, isFocused, refreshMembers]);
   109→
   110→  if (loading) return <Loading />;
   111→
   112→  return (
   113→    <ScreenLayout>
   114→      {isLeavingRoom && <Loading text="Leaving room..." />}
   115→      <Block flex={1} scrollable>
   116→        <GoBackHeader
   117→          margins={{ marginBottom: 40 }}
   118→          rightComp={
   119→            canEditRoom && (
   120→              <Button.Wrapper
   121→                onPress={() =>
   122→                  navigation.navigate("editRoom", {
   123→                    room,
   124→                  })
   125→                }
   126→              >
   127→                <Text>Edit</Text>
   128→              </Button.Wrapper>
   129→            )
   130→          }
   131→        />
   132→        <Block align="center" gap={12}>
   133→          <RoomImage room={room} width={80} height={80} />
   134→          <Text size={TextSize.medium} font="InstrumentSans-Bold">
   135→            {room.displayName()}
   136→          </Text>
   137→          {isDirect && roomInfo?.heroes[0]?.userId && (
   138→            <Text color={Colors.white50}>{roomInfo?.heroes[0]?.userId}</Text>
   139→          )}
   140→          <EncryptionStatus roomInfo={roomInfo} />
   141→        </Block>
   142→        <ActionButtons
   143→          isDirect={!!isDirect}
   144→          room={room}
   145→          members={members}
   146→          hasNoCallOption={hasNoCallOption}
   147→        />
   148→        <Topic room={room} topic={roomInfo?.topic} canEdit={canEditTopic} />
