   168→            >
   169→              <Block paddings={[0, 12]}>
   170→                <Block
   171→                  flexDirection="row"
   172→                  align="center"
   173→                  gap={12}
   174→                  paddings={[20, 0]}
   175→                  border={{ borderBottomWidth: 1, borderColor: Colors.white5 }}
   176→                >
   177→                  <Image
   178→                    source={require("assets/icons/user.png")}
   179→                    tintColor={Colors.white50}
   180→                    width={24}
   181→                    height={24}
   182→                  />
   183→                  <Text>View profile</Text>
