   194→                    />
   195→                  </Block>
   196→                </Block>
   197→              </Block>
   198→            </Button.Wrapper>
   199→          ) : (
   200→            <Button.Wrapper
   201→              onPress={() =>
   202→                navigation.navigate("roomMembers", {
   203→                  members,
   204→                  roomId: room.id(),
   205→                })
   206→              }
   207→            >
   208→              <Block paddings={[0, 12]}>
   209→                <Block
   210→                  flexDirection="row"
   211→                  align="center"
   212→                  gap={12}
   213→                  paddings={[20, 0]}
   214→                  border={{ borderBottomWidth: 1, borderColor: Colors.white5 }}
   215→                >
   216→                  <Image
   217→                    source={require("assets/icons/users.png")}
   218→                    tintColor={Colors.white50}
   219→                    width={24}
   220→                    height={24}
   221→                  />
   222→                  <Text>Members</Text>
   223→                  <Block
   224→                    margins={{ marginLeft: "auto" }}
   225→                    flexDirection="row"
   226→                    align="center"
   227→                    gap={8}
   228→                  >
   229→                    <Text color={Colors.white50}>
   230→                      (
   231→                      {
   232→                        members.filter(
   233→                          (member) =>
   234→                            member.membership?.tag ===
   235→                            MembershipState_Tags.Join,
   236→                        ).length
   237→                      }
   238→                      )
   239→                    </Text>
   240→                    <Image
   241→                      source={require("assets/icons/caret-left.png")}
   242→                      style={styles.caret}
   243→                      tintColor={Colors.white50}
   244→                    />
   245→                  </Block>
   246→                </Block>
   247→              </Block>
   248→            </Button.Wrapper>
   249→          )}
   250→          {!isDirect && canSeeRoles && (
   251→            <SettingsListItem
   252→              title="Security & Privacy"
   253→              icon={require("assets/icons/shield.png")}
   254→              showSeparator
   255→              onPress={() => navigation.navigate("roomSecurity", { room })}
   256→            />
   257→          )}
   258→          {!isDirect && canSeeRoles && (
   259→            <SettingsListItem
   260→              title="Roles & Permissions"
   261→              icon={require("assets/icons/user.png")}
   262→              showSeparator
   263→              onPress={() =>
   264→                navigation.navigate("roomRoles", {
   265→                  room,
   266→                  members,
   267→                  userPowerLevel: userPowerLevel ?? 0,
   268→                })
   269→              }
   270→            />
   271→          )}
   272→          <SettingsListItem
   273→            title="Media and Files"
   274→            icon={require("assets/icons/image.png")}
   275→            onPress={() => navigation.navigate("roomMedia", { room })}
   276→            showSeparator={!!pinnedEventIds.length}
   277→          />
   278→          {!!pinnedEventIds.length && (
   279→            <SettingsListItem
   280→              title="Pinned events"
   281→              icon={require("assets/icons/pin.png")}
   282→              onPress={() => navigation.navigate("pinnedEvents", { room })}
   283→            />
   284→          )}
   285→        </Block>
   286→        <LeaveRoom onPress={leaveRoom} />
   287→      </Block>
   288→    </ScreenLayout>
   289→  );
   290→};
   291→
   292→const styles = StyleSheet.create({
   293→  caret: {
   294→    transform: [{ rotate: "180deg" }],
   295→    width: 24,
   296→    height: 24,
   297→    marginLeft: "auto",
   298→  },
   299→});
