    10→export const RoomNotifications: React.FC<
    11→  NativeStackScreenProps<Routes, "roomNotifications">
    12→> = ({ navigation }) => {
    13→  const [notifications, setNotifications] = useState(true);
    14→  const [notificationType, setNotificationType] = useState<"all" | "mentions">(
    15→    "all",
