   286→    // Determine direct chat level
   287→    const dmRule = rules.global.underride?.find(
   288→      (r) => r.rule_id === ".m.rule.room_one_to_one",
   289→    );
   290→    const directChats: NotificationLevel = dmRule?.enabled ? "all" : "none";
   291→
   292→    // Determine mentions - check both new and old rules
   293→    const newMentionRule = rules.global.override?.find(
   294→      (r) => r.rule_id === ".m.rule.is_user_mention",
   295→    );
   296→    const oldMentionRule = rules.global.content?.find(
   297→      (r) => r.rule_id === ".m.rule.contains_user_name",
   298→    );
   299→    const displayNameRule = rules.global.override?.find(
   300→      (r) => r.rule_id === ".m.rule.contains_display_name",
   301→    );
